  "railway": ["327"], "dəmiryol": ["327"],
  "one-way": ["327"], "birtərəfli": ["327"],
  "registration": ["339"], "qeydiyyat": ["339"], "texniki": ["339"],
  "plate": ["342"], "nömrə": ["342"]
};

const matched = new Set();
for (const [k, ids] of Object.entries(kw)) {
  if (q.includes(k)) ids.forEach(id => matched.add(id));
}

if (matched.size === 0) {
  for (const a of knowledgeBase.articles) {
    if (q.split(" ").filter(w => w.length > 3).some(w => JSON.stringify(a).toLowerCase().includes(w))) {
      matched.add(a.id);
    }
  }
}

const results = knowledgeBase.articles.filter(a => matched.has(a.id)).slice(0, 4);
if (results.length === 0) {
  results.push(knowledgeBase.articles[0], knowledgeBase.articles[1], knowledgeBase.articles[2]);
}

let ctx = "AZERBAIJAN TRAFFIC FINES (Official Data from Cərimə və Ballar Cədvəli):\n";
for (const a of results) {
  ctx += `\nMaddə ${a.id} - ${a.title} (${a.titleEn}):\n`;
  for (const i of a.content) {
    ctx += `  ${i.sub}: ${i.v} - ${i.f} AZN${i.p ? `, ${i.p} bal/points` : ""}\n`;
  }
}

const requestBody = {
  model: "llama-3.1-8b-instant",
  messages: [
    {
      role: "system",
      content: "You answer questions about Azerbaijan traffic fines based on official data. Reply in the same language as the question (English or Azerbaijani). Be concise. Always cite the article number (Maddə) and state fines in AZN with penalty points (bal) where applicable. Use the exact data provided."
    },
    {
      role: "user",
      content: ctx + "\nQuestion: " + userMessage
    }
  ],
  temperature: 0.3,
  max_tokens: 600
};

return {
  json: {
    userMessage,
    chatId,
    context: ctx,
    requestBody
  }
};

const resp = $input.first().json;
if (resp.choices && resp.choices[0]) {
  return { json: { text: resp.choices[0].message.content } };
}
return { json: { text: "Sorry, I could not process your request. / Bağışlayın, sorğunuzu emal edə bilmədim." } };
